package com.mygo.music;

import android.app.*;
import android.content.*;
import android.media.*;
import android.net.Uri;
import android.os.SystemClock;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.*;

final class CompletionChecks {
    final Instrumentation test;final Context context;
    CompletionChecks(Instrumentation test){this.test=test;context=test.getTargetContext();}
    interface Ready{boolean get()throws Exception;}
    static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    void await(Ready condition,String message)throws Exception{long end=SystemClock.elapsedRealtime()+18000;while(SystemClock.elapsedRealtime()<end){boolean[] ready={false};Throwable[] error={null};test.runOnMainSync(()->{try{ready[0]=condition.get();}catch(Throwable failure){error[0]=failure;}});if(error[0]!=null)throw new AssertionError(message,error[0]);if(ready[0])return;SystemClock.sleep(40);}throw new AssertionError(message);}
    void install(PluginManager manager,String id,String mode,JSONArray settings,String script)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(bytes)){JSONObject manifest=new JSONObject().put("id",id).put("main","index.js").put("playback",mode).put("settings",settings);for(String name:new String[]{"plugin.json","index.js"}){zip.putNextEntry(new ZipEntry(name));zip.write((name.equals("plugin.json")?manifest.toString():script).getBytes("UTF-8"));zip.closeEntry();}}CountDownLatch done=new CountDownLatch(1);boolean[] success={false};String[] error={""};manager.installZipStream(new ByteArrayInputStream(bytes.toByteArray()),(ok,raw)->{success[0]=ok;error[0]=raw;done.countDown();});check(done.await(40,TimeUnit.SECONDS)&&success[0],"completion fixture install: "+error[0]);}
    PluginManager.PluginInfo info(PluginManager manager,String id){for(PluginManager.PluginInfo source:manager.list())if(source.id.equals(id))return source;throw new AssertionError("fixture source missing");}
    void cleanup(String id){PluginArchive.delete(new File(context.getFilesDir(),"plugins/"+id));context.getSharedPreferences("plugin_data_"+id,0).edit().clear().commit();context.getSharedPreferences("plugin_settings_"+id,0).edit().clear().commit();}
    void run()throws Exception{loudness();settings();remote();}
    private void loudness()throws Exception{
        check(PlaybackLoudness.gain(new JSONObject())==1,"unknown loudness was boosted");check(Math.abs(PlaybackLoudness.gain(new JSONObject().put("gain",3).put("peak",.8))-1.25)<.000001,"source peak limit ignored");check(Math.abs(PlaybackLoudness.gain(new JSONObject().put("gain",-6.6).put("peak",1))-Math.pow(10,-2.6/20))<.000001,"upstream preamp mismatch");
        File file=new File(context.getCacheDir(),"normalize-check.wav");try(FileOutputStream out=new FileOutputStream(file)){out.write(BackgroundPlaybackChecks.wav(10000));}MediaPlayer[] player={null};PlaybackLoudness level=new PlaybackLoudness();CountDownLatch prepared=new CountDownLatch(1);
        try{test.runOnMainSync(()->{try{player[0]=new MediaPlayer();player[0].setDataSource(file.getAbsolutePath());player[0].setOnPreparedListener(mp->{mp.start();prepared.countDown();});player[0].prepareAsync();}catch(Exception error){throw new RuntimeException(error);}});check(prepared.await(10,TimeUnit.SECONDS),"native gain player failed to prepare");await(()->player[0].isPlaying()&&player[0].getCurrentPosition()>150,"native clock did not run during gain check");test.runOnMainSync(()->{try{level.apply(player[0],80,false,true,new JSONObject().put("gain",-10).put("peak",1));check(level.appliedVolume>.39&&level.appliedVolume<.41,"actual player attenuation not applied");level.apply(player[0],80,false,false,new JSONObject().put("gain",-10));check(Math.abs(level.appliedVolume-.8)<.001,"disabling normalization kept old attenuation");level.apply(player[0],100,false,true,new JSONObject().put("gain",3).put("peak",.8));if(level.boostSupported){android.media.audiofx.LoudnessEnhancer effect=(android.media.audiofx.LoudnessEnhancer)FullPortChecks.field(level,"enhancer");check(effect!=null&&effect.getEnabled()&&Math.abs(effect.getTargetGain()-194)<3,"native gain effect not configured");}level.apply(player[0],100,true,false,new JSONObject());check(Math.abs(level.appliedVolume-.2)<.001&&level.appliedBoost==0,"ducking or old gain effect not reset");}catch(Exception error){throw new RuntimeException(error);}});
        }finally{test.runOnMainSync(()->{level.close();if(player[0]!=null)player[0].release();});file.delete();}
        RemoteCompletion end=new RemoteCompletion();JSONObject playing=new JSONObject().put("trackId","a").put("playing",true).put("position",9500).put("duration",10000);check(!end.update(playing),"playing track reported complete");end.pause();check(!end.update(new JSONObject(playing.toString()).put("playing",false).put("position",10000)),"user pause was treated as track completion");end.resume();end.update(playing);check(end.update(new JSONObject(playing.toString()).put("playing",false).put("position",10000)),"remote end position was ignored");end.update(playing);check(!end.update(new JSONObject())&&end.update(new JSONObject()),"empty end state not confirmed in two polls");end.update(playing);check(!end.update(new JSONObject().put("trackId","b").put("playing",true).put("position",0).put("duration",10000)),"provider auto advance duplicated host next");
    }
    private SourceSettings show(Activity activity,PluginManager manager,PluginManager.PluginInfo source)throws Exception{SourceSettings screen=new SourceSettings(activity,manager,source);test.runOnMainSync(screen::show);test.waitForIdleSync();return screen;}
    private void save(SourceSettings screen,String value){test.runOnMainSync(()->{try{Map<?,?> fields=(Map<?,?>)FullPortChecks.field(screen,"fields");((EditText)((PluginSettingField)fields.get("token")).view).setText(value);((AlertDialog)FullPortChecks.field(screen,"dialog")).getButton(AlertDialog.BUTTON_POSITIVE).performClick();}catch(Exception error){throw new RuntimeException(error);}});}
    private void settings()throws Exception{
        String id="completion-settings";cleanup(id);Activity activity=test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));PluginManager first=new PluginManager(activity),second=new PluginManager(activity);
        try{install(first,id,"stream",new JSONArray().put(new JSONObject().put("key","token")),"export async function setSetting({key,value}){const start=host.setting(key);await new Promise(r=>setTimeout(r,180));const end=host.setting(key);if(value==='reject')throw Error('fixture rejected');host.storage.set('writes',[...(host.storage.get('writes')||[]),{value,start,end}]);}");PluginManager.PluginInfo source=info(first,id);SourceSettings one=show(activity,first,source),two=show(activity,second,source);save(one,"one");save(two,"two");await(()->new JSONArray(context.getSharedPreferences("plugin_data_"+id,0).getString("writes","[]")).length()==2,"cross-dialog setting writes did not finish");JSONArray writes=new JSONArray(context.getSharedPreferences("plugin_data_"+id,0).getString("writes","[]"));for(int i=0;i<2;i++){JSONObject row=writes.getJSONObject(i);String expected=i==0?"one":"two";check(row.getString("value").equals(expected)&&row.getString("start").equals(expected)&&row.getString("end").equals(expected),"another dialog changed a setting during its acknowledgement");}
            SourceSettings untouched=show(activity,first,source),changed=show(activity,second,source);save(changed,"three");await(()->context.getSharedPreferences("plugin_settings_"+id,0).getString("token","").equals("three")&&((Set<?>)FullPortChecks.field(changed,"pending")).isEmpty(),"third setting missing");test.runOnMainSync(()->{try{((AlertDialog)FullPortChecks.field(untouched,"dialog")).getButton(AlertDialog.BUTTON_POSITIVE).performClick();}catch(Exception error){throw new RuntimeException(error);}});check(context.getSharedPreferences("plugin_settings_"+id,0).getString("token","").equals("three"),"untouched old window reverted a newer value");
            SourceSettings rejected=show(activity,first,source);save(rejected,"reject");await(()->((Set<?>)FullPortChecks.field(rejected,"pending")).isEmpty()&&context.getSharedPreferences("plugin_settings_"+id,0).getString("token","").equals("three"),"failed source setting was not rolled back");SourcePlaylistUiChecks.click(test,"恢复原值");test.runOnMainSync(()->{try{((AlertDialog)FullPortChecks.field(rejected,"dialog")).dismiss();}catch(Exception error){throw new RuntimeException(error);}});
        }finally{test.runOnMainSync(()->{first.close();second.close();activity.finish();});cleanup(id);}
    }
    private void remote()throws Exception{
        String id="completion-radio";cleanup(id);MainActivity activity=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));PluginManager manager=new PluginManager(activity);PlaybackService[] service={null};await(()->{service[0]=(PlaybackService)FullPortChecks.field(activity,"playbackService");return service[0]!=null;},"remote radio service unavailable");
        try{install(manager,id,"remote",new JSONArray(),"let ids=[],current='',began=0,paused=false,held=0;export function remotePlay(args){ids=args.ids;current=ids[args.start];began=Date.now()-args.position;paused=false;host.storage.set('remoteQueue',args);return {};}export function remoteState(){const position=Math.min(2200,paused?held:Date.now()-began);return {trackId:current,position,duration:2200,playing:!paused&&position<2200,volume:80};}export function remotePause(){held=Math.min(2200,Date.now()-began);paused=true;}export function remoteResume(){began=Date.now()-held;paused=false;}export function stationNext({id}){if(id!=='radio')throw Error('station lost');return [{id:'b',name:'b'},{id:'c',name:'c'}];}");JSONArray queue=new JSONArray().put(new JSONObject().put("uri","plugin://"+id+"?id=a").put("title","a").put("stationId","radio"));test.runOnMainSync(()->{try{PlaybackService.startQueue(activity,queue,0,0,80,false,false,"high");}catch(Exception error){throw new RuntimeException(error);}});await(()->service[0].snapshot().remote&&service[0].snapshot().playing,"remote fixture never started");test.runOnMainSync(service[0]::pause);SystemClock.sleep(2600);test.runOnMainSync(()->check(service[0].snapshot().title.equals("a")&&!service[0].snapshot().playing,"paused remote radio advanced by itself"));test.runOnMainSync(service[0]::resume);await(()->service[0].snapshot().title.equals("b")&&service[0].snapshot().playing,"remote radio did not advance to prefetched batch after true completion");JSONObject sent=new JSONObject(context.getSharedPreferences("plugin_data_"+id,0).getString("remoteQueue","{}"));check(sent.getJSONArray("ids").getString(sent.getInt("start")).equals("b"),"remote device received an outdated radio queue");
        }finally{test.runOnMainSync(()->{service[0].stopPlayback();manager.close();activity.finish();});cleanup(id);}
    }
}
